import heapq


def topStudents(positive, negative, reports, k):
    pos, neg = set(positive), set(negative)
    score = {}
    for row in reports:
        sid = row[0]
        sc = score.get(sid, 0)
        for w in row[1:]:
            if w in pos:
                sc += 3
            elif w in neg:
                sc -= 1
        score[sid] = sc
    heap = []
    for sid, sc in score.items():
        heapq.heappush(heap, (sc, -sid))
        if len(heap) > k:
            heapq.heappop(heap)
    heap.sort(reverse=True)
    return [-s for _, s in heap]
